241						logger.Info("newer version available", zap.String("latest_version", releaseInfo.LatestVersion), zap.String("url", releaseInfo.LatestVersionURL))
242					}
243				} else {
244					if isConsole {
245						color.Green("You are currently running the latest version of Flipt [%s]!", releaseInfo.CurrentVersion)
246					} else {
247						logger.Info("running latest version", zap.String("current_version", releaseInfo.CurrentVersion))
248					}
249				}
250			}
251		}
252	
253		info := info.Flipt{
254			Commit:           commit,
255			BuildDate:        date,
256			GoVersion:        goVersion,
257			Version:          releaseInfo.CurrentVersion,
258			LatestVersion:    releaseInfo.LatestVersion,
259			LatestVersionURL: releaseInfo.LatestVersionURL,
260			IsRelease:        isRelease,
261			UpdateAvailable:  releaseInfo.UpdateAvailable,
262		}
263	
264		if !isRelease {
265			logger.Debug("not a release version, disabling telemetry")
266			cfg.Meta.TelemetryEnabled = false
267		}
268	
269		if os.Getenv("CI") == "true" || os.Getenv("CI") == "1" {
270			logger.Debug("CI detected, disabling telemetry")
271			cfg.Meta.TelemetryEnabled = false
272		}
273	
274		g, ctx := errgroup.WithContext(ctx)
275	
276		if err := initLocalState(); err != nil {
277			logger.Debug("disabling telemetry, state directory not accessible", zap.String("path", cfg.Meta.StateDirectory), zap.Error(err))
278			cfg.Meta.TelemetryEnabled = false
279		} else {
280			logger.Debug("local state directory exists", zap.String("path", cfg.Meta.StateDirectory))
281		}
282	
283		if cfg.Meta.TelemetryEnabled && isRelease {
284			logger := logger.With(zap.String("component", "telemetry"))
285	
286			g.Go(func() error {
287				reporter, err := telemetry.NewReporter(*cfg, logger, analyticsKey, info)
288				if err != nil {
289					logger.Debug("initializing telemetry reporter", zap.Error(err))
290					return nil
291				}
292	
293				defer func() {
294					_ = reporter.Shutdown()
295				}()
